   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: #141c32;
       --panel-border: #33415c;
       --panel-shadow: #050814;
       --text: #f3f7ff;
       --muted: #b9c4dd;
       --accent: #7cc7ff;
       --accent-strong: #a4ddff;
       --field-bg: #0f172b;
       --field-border: #4a5a7d;
       --error: #ff9a9a;
       --error-border: #ff6b6b;
       --success: #9fe2b3;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top, #162445 0, var(--bg) 45%),
         linear-gradient(180deg, #08111f 0%, var(--bg) 100%);
       color: var(--text);
     }

     a {
       color: var(--accent-strong);
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: -3rem;
       padding: 0.75rem 1rem;
       background: var(--text);
       color: #000;
       border-radius: 0.75rem;
       z-index: 10;
     }

     .skip-link:focus {
       top: 1rem;
     }

     .page-shell {
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 2rem 1rem;
     }

     .card {
       width: min(100%, 42rem);
       background: linear-gradient(180deg, #18223d 0%, var(--panel) 100%);
       border: 1px solid var(--panel-border);
       border-radius: 1.5rem;
       padding: clamp(1.5rem, 4vw, 2.5rem);
       box-shadow: 0 1.5rem 3.5rem 0 var(--panel-shadow);
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       font-size: 0.9rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 2.8rem);
       line-height: 1.1;
     }

     .intro {
       margin: 1rem 0 2rem;
       max-width: 50ch;
       color: var(--muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 1.25rem;
     }

     .form-field {
       display: grid;
       gap: 0.5rem;
       min-width: 0;
     }

     label {
       font-weight: 600;
     }

     .required-indicator {
       color: var(--accent-strong);
       margin-left: 0.25rem;
     }

     .field-input {
       width: 100%;
       padding: 0.95rem 1rem;
       border: 1px solid var(--field-border);
       border-radius: 0.9rem;
       background: var(--field-bg);
       color: var(--text);
       font: inherit;
       outline: 2px solid transparent;
       outline-offset: 2px;
       transition: border-color 0.2s ease, box-shadow 0.2s ease;
     }

     .field-input::placeholder {
       color: var(--muted);
     }

     .field-input:focus {
       border-color: var(--accent);
       box-shadow: 0 0 0 0.2rem #183c5c;
     }

     .field-input[aria-invalid="true"] {
       border-color: var(--error-border);
       box-shadow: 0 0 0 0.2rem #4d1f27;
     }

     .helper-text,
     .error-text,
     .status-message {
       font-size: 0.95rem;
       line-height: 1.4;
       overflow-wrap: anywhere;
     }

     .helper-text {
       color: var(--muted);
     }

     .error-text {
       color: var(--error);
       min-height: 1.4em;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
       margin-top: 0.25rem;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.4rem;
       font: inherit;
       font-weight: 700;
       background: linear-gradient(180deg, #7fd0ff 0%, #59b6f3 100%);
       color: #04111d;
       cursor: pointer;
       outline: 2px solid transparent;
       outline-offset: 2px;
     }

     button:hover {
       background: linear-gradient(180deg, #9bdcff 0%, #72c4fb 100%);
     }

     button:focus-visible,
     .field-input:focus-visible,
     .skip-link:focus-visible {
       outline-color: var(--accent-strong);
     }

     .status-message {
       color: var(--success);
       margin: 0;
     }

     @media (max-width: 30rem) {
       .card {
         border-radius: 1rem;
         padding: 1.25rem;
       }
     }

     @media (forced-colors: active) {
       body {
         background: Canvas;
         color: CanvasText;
       }

       .card,
       .field-input,
       button,
       .skip-link {
         background: Canvas;
         color: CanvasText;
         border: 1px solid ButtonBorder;
         box-shadow: none;
       }

       .helper-text,
       .error-text,
       .status-message,
       .eyebrow {
         color: CanvasText;
       }

       button,
       .field-input,
       .skip-link {
         outline-color: transparent;
       }

       button:focus-visible,
       .field-input:focus-visible,
       .skip-link:focus-visible {
         outline-color: Highlight;
       }
     }
   </style>
 </head>
